cd /work/workspace && python3 - <<'PY'
import re,glob
libs={f:open(f).read() for f in sorted(glob.glob('library/*.md'))}
alltext="\n".join(libs.values())
def present(n):
    return bool(re.search(r'art(?:s?\.?)\s*(º\s*)?'+n+r'\s*º', alltext)) or bool(re.search(r'art(?:s?\.?)\s*'+n+r'[^º0-9]', alltext))
nums=set()
for f in sorted(glob.glob('deliverable/*')):
    t=open(f).read()
    for m in re.finditer(r'art(?:s?\.?)\s*(?:§+\s*)?(\d+)\s*º?', t):
        nums.add(m.group(1))
for n in sorted(nums,key=int):
    print(n, 'LIB' if present(n) else '*** NOT IN LIBRARY ***')
print('--- CPC mentions in library ---')
print([l for l in alltext.splitlines() if 'CPC' in l or '224' in l])
print('--- LC 123 mentions in deliverables ---')
for f in sorted(glob.glob('deliverable/*')):
    for i,l in enumerate(open(f).read().splitlines(),1):
        if '123' in l: print(f, i, l.strip()[:200])
print('--- art.6/7/8/9/10 in library (raw) ---')
for f,txt in libs.items():
    hits=[l.strip()[:120] for l in txt.splitlines() if re.search(r'art(?:s?\.?)\s*(6|7|8|9|10)\s*º', l)]
    if hits: print(f, hits[:6])
PY

